      val: (I, s) => s.length,
      solve: (I) => { const g = I.grid, [A] = comps(g, (r, c) => g[r][c]); const d = bfs(g, A, () => true), par = {}; const q = A.slice(); const seen = new Set(A.map(([r, c]) => key(r, c))); for (let h = 0; h < q.length; h++) { const [r, c] = q[h]; for (const [dy, dx] of D4) { const a = r + dy, b = c + dx; if (!inside(g, a, b) || seen.has(key(a, b))) continue; seen.add(key(a, b)); par[key(a, b)] = [r, c]; if (g[a][b] && !A.some(([y, x]) => y === a && x === b)) { const out = []; let cur = [r, c]; while (g[cur[0]][cur[1]] === 0) { out.push(cur); cur = par[key(...cur)]; } return out; } q.push([a, b]); } } void d; return []; },
