      solve: (I) => { const g = I.grid, n = g.length, prev = {}, q = [[0, 0]], seen = new Set(["0,0"]); for (let h = 0; h < q.length; h++) { const [r, c] = q[h]; if (r === n - 1 && c === n - 1) break; for (const [dy, dx] of D8) { const a = r + dy, b = c + dx; if (inside(g, a, b) && g[a][b] === "" && !seen.has(key(a, b))) { seen.add(key(a, b)); prev[key(a, b)] = [r, c]; q.push([a, b]); } } } const p = [[n - 1, n - 1]]; while (p[0][0] || p[0][1]) p.unshift(prev[key(...p[0])]); return p; },
