      valid: (I, p) => { const e = [I.grid.length - 1, I.grid[0].length - 1]; if (p[p.length - 1][0] !== e[0] || p[p.length - 1][1] !== e[1]) return "reach the bottom-right corner"; return p.filter(([r, c]) => I.grid[r][c] === "#").length <= I.k || `you broke more than ${I.k} walls`; },
      val: (I, p) => p.length - 1,
      solve: (I) => { const g = I.grid, n = g.length, m = g[0].length, st = (r, c, k) => `${r},${c},${k}`, prev = {}, q = [[0, 0, I.k]], seen = new Set([st(0, 0, I.k)]); let end = null; for (let h = 0; h < q.length && !end; h++) { const [r, c, k] = q[h]; for (const [dy, dx] of D4) { const a = r + dy, b = c + dx; if (!inside(g, a, b)) continue; const nk = k - (g[a][b] === "#" ? 1 : 0); if (nk < 0 || seen.has(st(a, b, nk))) continue; seen.add(st(a, b, nk)); prev[st(a, b, nk)] = [r, c, k]; if (a === n - 1 && b === m - 1) { end = [a, b, nk]; break; } q.push([a, b, nk]); } } if (!end) return null; const p = [end]; while (p[0][0] || p[0][1] || p[0][2] !== I.k) p.unshift(prev[st(...p[0])]); return p.map(([r, c]) => [r, c]); },
