      solve: (I) => { const g = I.grid, n = g.length, m = g[0].length; const best = g.map((r) => r.slice()), from = G2(n, m, () => -1); for (let r = 1; r < n; r++) for (let c = 0; c < m; c++) { let b = Infinity; for (const d of [-1, 0, 1]) if (c + d >= 0 && c + d < m && best[r - 1][c + d] < b) { b = best[r - 1][c + d]; from[r][c] = c + d; } best[r][c] += b; } let c = best[n - 1].indexOf(H.min(best[n - 1])); const p = []; for (let r = n - 1; r >= 0; r--) { p.unshift([r, c]); c = from[r][c]; } return p; },
