      ans: (I) => { const g = I.grid, path = [I.s], seen = new Set([key(...I.s)]); const go = () => { const [y, x] = path[path.length - 1]; if (path.length === I.open) return y === I.e[0] && x === I.e[1]; for (const [dy, dx] of D4) { const a = y + dy, b = x + dx; if (inside(g, a, b) && !g[a][b] && !seen.has(key(a, b))) { seen.add(key(a, b)); path.push([a, b]); if (go()) return true; path.pop(); seen.delete(key(a, b)); } } return false; }; go(); return path; },
