      solve: (I) => { const g = I.grid, memo = new Map(); const f = (r, c) => { const k = key(r, c); if (memo.has(k)) return memo.get(k); let best = [[r, c]]; for (const [dy, dx] of D4) { const a = r + dy, b = c + dx; if (inside(g, a, b) && g[a][b] > g[r][c]) { const t = f(a, b); if (t.length + 1 > best.length) best = [[r, c], ...t]; } } memo.set(k, best); return best; }; let best = []; H.cells(g.length, g[0].length).forEach(([r, c]) => { const t = f(r, c); if (t.length > best.length) best = t; }); return best; },
